import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:8081/api/view-teachers')
      .then(res => setTeachers(res.data))
      .catch(err => console.error(err));
  }, []);

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>Manage Teachers</h2>
      
      <div style={{ backgroundColor: 'white', borderRadius: '8px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
            <tr>
              <th style={{ padding: '15px', color: '#475569' }}>Full Name</th>
              <th style={{ padding: '15px', color: '#475569' }}>Subject</th>
              <th style={{ padding: '15px', color: '#475569' }}>Email Address</th>
              <th style={{ padding: '15px', color: '#475569' }}>Contact Number</th>
            </tr>
          </thead>
          <tbody>
            {teachers.length > 0 ? teachers.map((teacher) => (
              <tr key={teacher.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={{ padding: '15px', fontWeight: 'bold' }}>{teacher.name}</td>
                <td style={{ padding: '15px' }}>{teacher.subject}</td>
                <td style={{ padding: '15px' }}>{teacher.email}</td>
                <td style={{ padding: '15px' }}>{teacher.phone_number}</td>
              </tr>
            )) : (
              <tr><td colSpan="4" style={{ padding: '20px', textAlign: 'center', color: '#ef4444' }}>No lecturers found in Database.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
